"""
基于大模型的多轮跨域对话语料生成脚本（完整优化版）
- 严格使用CROSS_DOMAIN_ASSOCIATIONS中的映射规则
- 前N-1轮使用映射的第一个子类，最后一轮使用映射的第二个子类
- 支持单轮语料生成
- 根据目标域动态选择改写类型（传统域3种，非传统域4种）
- 重点利用映射信息，强调语境关联
- Excel输出包含完整的映射规则信息
"""

import asyncio
from enum import Enum
from datetime import datetime, timedelta
from openpyxl import Workbook
from openpyxl.styles import Font, Alignment, PatternFill
import random
from typing import List, Dict, Optional, Tuple, Union
import re
import sys
import os

sys.path.append(os.path.join(os.path.dirname(__file__), '../../..'))

from nanoai.model.llm import allm
from nanoai.utils.async_utils import amap


class GenerationMode(Enum):
    """生成模式枚举"""
    CUSTOM = "custom"
    CONTEXT = "context"


class TraditionalRewriteType(Enum):
    """传统域的改写类型枚举 - 3种改写场景"""
    NONE = "无"
    PRONOUN = "指代"  # 场景1：有代词，替换为上下文正确实体
    ELLIPSIS = "省略"  # 场景2：无代词，根据上下文补充实体
    CLARIFICATION = "澄清"  # 场景3：语义复杂需剔除无效信息，规整为执行指令


class NonTraditionalRewriteType(Enum):
    """非传统域的改写类型枚举 - 4种标准改写类型"""
    NONE = "无"
    PRONOUN = "指代"  # 场景1：有代词，替换为上下文正确实体
    ELLIPSIS = "省略"  # 场景2：无代词，根据上下文补充实体
    VAGUE = "模糊"  # 场景2变体：带模糊词但需要补充实体
    CLARIFICATION = "澄清"  # 场景3：语义复杂需剔除无效信息，规整为执行指令


# 统一类型（用于类型提示）
RewriteType = Union[TraditionalRewriteType, NonTraditionalRewriteType]



class MultiRoundSession:
    """多轮对话会话（支持跨域）"""

    def __init__(self, session_id: str = None):
        self.session_id = session_id or datetime.now().strftime("%Y%m%d%H%M%S%f")
        self.rounds = []
        self.timestamp = datetime.now().isoformat()
        self.is_cross_domain = False
        self.cross_domain_association = None  # 保存CROSS_DOMAIN_ASSOCIATIONS中的映射规则

    def add_round(self, question: str, domain: str, sub_category: str,
                  answer: str = "", rewrite_type: str = "无",
                  expanded_question: str = ""):
        round_num = len(self.rounds) + 1
        self.rounds.append({
            'round': round_num,
            'question': question,
            'domain': domain,
            'sub_category': sub_category,
            'answer': answer,
            'rewrite_type': rewrite_type if round_num > 1 else "无",
            'expanded_question': expanded_question if round_num > 1 else ""
        })

        if round_num > 1:
            domains = [r['domain'] for r in self.rounds]
            if len(set(domains)) > 1:
                self.is_cross_domain = True

    def set_cross_domain_association(self, association_tuple: Optional[Tuple[str, str, str]], 
                                     domain1_key: Optional[str] = None, 
                                     domain2_key: Optional[str] = None):
        """
        设置CROSS_DOMAIN_ASSOCIATIONS中的映射规则
        
        Args:
            association_tuple: (sub_category1, sub_category2, scenario_description) 元组
            domain1_key: 源域键名（可选，如果未提供则从子类别全名推断）
            domain2_key: 目标域键名（可选，如果未提供则从子类别全名推断）
        """
        if association_tuple:
            sub1, sub2, scenario = association_tuple

            # 如果未提供域键名，使用简单的解析（仅用于显示，不用于验证）
            if domain1_key is None:
                # 简单的解析方法：取子类别全名的前缀作为显示名称
                # 注意：这只是用于显示，实际的域键名应该通过 _find_domain_for_subcategory 获取
                parts1 = sub1.split('-', 1)
                domain1_key = parts1[0] if len(parts1) > 0 else sub1
            
            if domain2_key is None:
                parts2 = sub2.split('-', 1)
                domain2_key = parts2[0] if len(parts2) > 0 else sub2

            self.cross_domain_association = {
                'source_domain': domain1_key,
                'target_domain': domain2_key,
                'source_sub_category': sub1,
                'target_sub_category': sub2,
                'scenario_description': scenario,
                'display_domain_mapping': f"{domain1_key} → {domain2_key}",
                'display_subcategory_mapping': f"{sub1} → {sub2}",
                'full_display': f"域映射: {domain1_key} → {domain2_key}\n子类映射: {sub1} → {sub2}\n场景: {scenario}"
            }

    def get_domain_mapping(self) -> str:
        """获取domain映射"""
        if self.cross_domain_association:
            return self.cross_domain_association.get('display_domain_mapping', '无')
        return '无'

    def get_subcategory_mapping(self) -> str:
        """获取子类映射"""
        if self.cross_domain_association:
            return self.cross_domain_association.get('display_subcategory_mapping', '无')
        return '无'

    def get_scenario_description(self) -> str:
        """获取场景描述"""
        if self.cross_domain_association:
            return self.cross_domain_association.get('scenario_description', '无')
        return '无'

    def get_cross_domain_association_full(self) -> str:
        """获取完整映射规则描述"""
        if self.cross_domain_association:
            return self.cross_domain_association.get('full_display', '无映射规则')
        return '无映射规则'

    def get_total_rounds(self) -> int:
        """获取总轮次数"""
        return len(self.rounds)

    def get_domain_path(self) -> str:
        """获取跨域路径"""
        if not self.rounds:
            return ""

        domains = [r['domain'] for r in self.rounds]
        unique_domains = []
        for d in domains:
            if not unique_domains or unique_domains[-1] != d:
                unique_domains.append(d)

        return " -> ".join(unique_domains)

    def get_subcategory_path(self) -> str:
        """获取子类路径"""
        if not self.rounds:
            return ""

        path_parts = []
        for r in self.rounds:
            part = f"{r['domain']}-{r['sub_category']}"
            if not path_parts or path_parts[-1] != part:
                path_parts.append(part)

        return " -> ".join(path_parts)

    def get_rewrite_types(self) -> str:
        """获取包含的改写类型"""
        rewrite_types = []
        for r in self.rounds:
            rt = r.get('rewrite_type', '无')
            if rt != '无' and rt not in rewrite_types:
                rewrite_types.append(rt)

        return ", ".join(rewrite_types) if rewrite_types else "无"


class LLMCorpusGenerator:
    """基于大模型的语料生成器（完整优化版）"""

    def __init__(self):
        self.sessions = []
        self.domain_config = DOMAIN_CONFIG
        self.failed_tasks = []

        # 动态识别传统域的键名
        self.traditional_domain_key = self._get_traditional_domain_key()
        print("使用新的config模块，模型配置在core.py中直接设置")
        print(f"检测到的传统域键名: {self.traditional_domain_key}")

    def _get_traditional_domain_key(self) -> str:
        """动态获取传统域的键名"""
        possible_keys = ["传统垂域", "传统域", "传统助手"]
        for key in possible_keys:
            if key in self.domain_config:
                return key
        return "传统垂域"  # 默认值

    def _is_traditional_domain(self, domain: str) -> bool:
        """判断是否为传统域（支持多种命名）"""
        return (domain == "传统垂域" or
                domain == "传统域" or
                domain == "传统助手" or
                domain == self.traditional_domain_key)

    def _find_domain_for_subcategory(self, sub_category_full: str) -> Optional[str]:
        """
        查找子类别全名所属的域键名
        
        Args:
            sub_category_full: 子类别全名，格式如 "导航-直接导航需求"
        
        Returns:
            域键名，如 "传统垂域"，如果找不到则返回 None
        """
        # 遍历所有域，查找包含该子类别的域
        for domain_key, domain_info in self.domain_config.items():
            if isinstance(domain_info, dict) and 'sub_categories' in domain_info:
                sub_categories = domain_info['sub_categories']
                # 检查子类别全名是否在该域的配置中
                if sub_category_full in sub_categories:
                    return domain_key
        return None

    async def generate_corpus(self, prompt, max_retries=3):
        """根据 prompt 生成语料（带延迟避免API限制）"""
        for attempt in range(max_retries):
            try:
                await asyncio.sleep(0.1)
                result = await allm(prompt)
                return result.output
            except Exception as e:
                if attempt < max_retries - 1:
                    print(f"    重试 {attempt + 1}/{max_retries}... 错误: {str(e)[:50]}")
                    await asyncio.sleep(2 ** attempt)
                else:
                    raise e

    def _get_sub_category_info(self, domain: str, sub_category: str) -> Dict:
        """获取子类的详细信息"""
        domain_info = self.domain_config.get(domain, {})
        sub_cats = domain_info.get('sub_categories', {})
        return sub_cats.get(sub_category, {
            'description': sub_category,
            'examples': []
        })

    def _get_rewrite_type_enum(self, domain: str, rewrite_type_str: str) -> RewriteType:
        """根据域和字符串获取对应的改写类型枚举"""
        if self._is_traditional_domain(domain):
            if rewrite_type_str == "指代":
                return TraditionalRewriteType.PRONOUN
            elif rewrite_type_str == "省略":
                return TraditionalRewriteType.ELLIPSIS
            elif rewrite_type_str == "澄清":
                return TraditionalRewriteType.CLARIFICATION
            else:
                return TraditionalRewriteType.NONE
        else:
            if rewrite_type_str == "指代":
                return NonTraditionalRewriteType.PRONOUN
            elif rewrite_type_str == "省略":
                return NonTraditionalRewriteType.ELLIPSIS
            elif rewrite_type_str == "模糊":
                return NonTraditionalRewriteType.VAGUE
            elif rewrite_type_str == "澄清":
                return NonTraditionalRewriteType.CLARIFICATION
            else:
                return NonTraditionalRewriteType.NONE

    def _normalize_rewrite_type_for_domain(self, rewrite_type: RewriteType, domain: str) -> RewriteType:
        """标准化改写类型到对应域的枚举类型"""
        is_traditional = self._is_traditional_domain(domain)

        if is_traditional:
            if isinstance(rewrite_type, TraditionalRewriteType):
                return rewrite_type
            elif isinstance(rewrite_type, NonTraditionalRewriteType):
                if rewrite_type == NonTraditionalRewriteType.PRONOUN:
                    return TraditionalRewriteType.PRONOUN
                elif rewrite_type == NonTraditionalRewriteType.ELLIPSIS:
                    return TraditionalRewriteType.ELLIPSIS
                elif rewrite_type == NonTraditionalRewriteType.CLARIFICATION:
                    return TraditionalRewriteType.CLARIFICATION
                elif rewrite_type == NonTraditionalRewriteType.VAGUE:
                    return TraditionalRewriteType.CLARIFICATION
                else:
                    return TraditionalRewriteType.NONE
            else:
                return TraditionalRewriteType.NONE
        else:
            if isinstance(rewrite_type, NonTraditionalRewriteType):
                return rewrite_type
            elif isinstance(rewrite_type, TraditionalRewriteType):
                if rewrite_type == TraditionalRewriteType.PRONOUN:
                    return NonTraditionalRewriteType.PRONOUN
                elif rewrite_type == TraditionalRewriteType.ELLIPSIS:
                    return NonTraditionalRewriteType.ELLIPSIS
                elif rewrite_type == TraditionalRewriteType.CLARIFICATION:
                    return NonTraditionalRewriteType.CLARIFICATION
                else:
                    return NonTraditionalRewriteType.NONE
            else:
                return NonTraditionalRewriteType.NONE

    def _get_rewrite_type_str(self, rewrite_type: RewriteType) -> str:
        """将改写类型枚举转换为字符串"""
        return rewrite_type.value

    async def generate_multi_round_session(self, rounds_config: List[Dict],
                                           task_id: str = "") -> MultiRoundSession:
        """生成一个完整的多轮对话会话"""
        session = MultiRoundSession()
        conversation_history = []

        for round_idx, round_config in enumerate(rounds_config, 1):
            domain = round_config['domain']
            sub_category = round_config['sub_category']
            mode = round_config.get('mode', 'custom')
            rewrite_type_str = round_config.get('rewrite_type', '无')
            is_cross_domain_round = round_config.get('is_cross_domain', False)
            mapping_info = round_config.get('mapping_info', None)
            source_domain = round_config.get('source_domain', None)

            context = self._build_context_from_history(conversation_history)

            if mode == 'custom':
                mapping_info_first = mapping_info if mapping_info else None
                question = await self._generate_question(domain, sub_category, mapping_info_first)
                expanded_question = ""
                rewrite_type_str_to_save = "无"
            else:
                if not rewrite_type_str or rewrite_type_str == '无':
                    if self._is_traditional_domain(domain):
                        rewrite_type_enum = TraditionalRewriteType.ELLIPSIS
                    else:
                        rewrite_type_enum = NonTraditionalRewriteType.ELLIPSIS
                else:
                    rewrite_type_enum = self._get_rewrite_type_enum(domain, rewrite_type_str)

                rewrite_type_enum = self._normalize_rewrite_type_for_domain(rewrite_type_enum, domain)

                question = await self._generate_context_question(
                    domain, sub_category, context,
                    rewrite_type_enum, is_cross_domain_round, mapping_info, source_domain
                )

                expanded_question = await self._expand_question(
                    question, context, domain, sub_category,
                    rewrite_type_enum, mapping_info, source_domain
                )

                rewrite_type_str_to_save = self._get_rewrite_type_str(rewrite_type_enum)

            if not question:
                print(f"  [{task_id}] ✗ 第{round_idx}轮生成失败")
                continue

            answer = await self._generate_answer(domain, sub_category, question, context)
            session.add_round(question, domain, sub_category, answer, rewrite_type_str_to_save, expanded_question)

            conversation_history.append({'role': 'user', 'content': question})
            conversation_history.append({'role': 'assistant', 'content': answer})

        self.sessions.append(session)
        return session

    def _build_context_from_history(self, history: List[Dict]) -> str:
        """从对话历史构建上下文字符串"""
        if not history:
            return ""
        context_parts = []
        for i, item in enumerate(history, 1):
            role = "用户" if item['role'] == 'user' else "助手"
            context_parts.append(f"第{i}轮：{role}：{item['content']}")
        return "\n".join(context_parts)

    async def _generate_question(self, domain: str, sub_category: str,
                                 mapping_info: Optional[Dict] = None) -> str:
        """生成第一轮完整问题（映射信息仅作背景参考，不强依赖）"""
        domain_info = self.domain_config.get(domain, {})
        domain_desc = domain_info.get('description', domain)
        sub_info = self._get_sub_category_info(domain, sub_category)
        sub_desc = sub_info.get('description', sub_category)
        examples = sub_info.get('examples', [])

        intent_guide = DOMAIN_INTENT_GUIDE.get(domain, {})
        intent_type = intent_guide.get('intent_type', '')
        intent_desc = intent_guide.get('description', '')
        key_point = intent_guide.get('key_point', '')
        correct_ex = intent_guide.get('correct_examples', [])
        wrong_ex = intent_guide.get('wrong_examples', [])

        examples_text = "\n".join([f"  - {ex}" for ex in examples[:6]]) if examples else ""
        correct_text = "\n".join([f"  ✓ {ex}" for ex in correct_ex[:4]]) if correct_ex else ""
        wrong_text = "\n".join([f"  ✗ {ex}" for ex in wrong_ex[:4]]) if wrong_ex else ""

        mapping_guidance = ""
        if mapping_info and mapping_info.get("is_part_of_mapping"):
            target_domain = mapping_info.get("target_domain", "")
            target_sub = mapping_info.get("target_sub_category", "")
            scenario_desc = mapping_info.get("scenario_description", "")

            mapping_guidance = f"""

【背景信息】（仅供参考，不影响生成）
这是跨域对话的第一轮，后续会转换到{target_domain}垂域的{target_sub}子类。
场景描述：{scenario_desc}
注意：当前问题应该专注于"{sub_category}"，不需要提前涉及目标域内容。
"""

        prompt = f"""你是一个专业的语料生成专家。请生成{domain}垂域中关于"{sub_category}"的用户查询问题。

【垂域说明】
{domain}：{domain_desc}

【子类说明】
{sub_category}：{sub_desc}

【意图类型】核心要求
本垂域的意图类型是"{intent_type}"：{intent_desc}
关键点：{key_point}

本垂域正确的问题示例：
{correct_text if correct_text else "  （参考典型示例）"}
{f'''
应该避免的问题示例（属于其他垂域）：
{wrong_text}''' if wrong_text else ''}
{mapping_guidance}

【典型示例】（严格参考这些示例，但可以创造性地变化表达方式）
{examples_text if examples_text else "  （无具体示例，请根据子类说明生成）"}

【生成要求】
1. 生成1条完整的、独立的用户查询问题
2. 问题必须严格属于"{sub_category}"的范围
3. 问题的意图类型必须是"{intent_type}"
4. 严格参考典型示例，确保问题风格正确
5. 在保持意图类型正确的前提下，可以灵活变化表达方式，保持多样性
6. 直接返回问题，不要编号、不要解释、不要前缀

问题："""

        response = await self.generate_corpus(prompt)
        lines = self._parse_lines(response)
        return lines[0] if lines else ""

    async def _generate_context_question(self, domain: str, sub_category: str,
                                         context: str, rewrite_type: RewriteType,
                                         is_cross_domain: bool = False,
                                         mapping_info: Optional[Dict] = None,
                                         source_domain: Optional[str] = None) -> str:
        """
        生成基于上下文的追问（重点利用映射信息）

        满足条件：
        1. 语境符合第一轮的历史问答（追问要基于前面的对话上下文）
        2. 符合当前垂域-子类（映射指定的垂域和子类）
        """
        domain_info = self.domain_config.get(domain, {})
        domain_desc = domain_info.get('description', domain)
        sub_info = self._get_sub_category_info(domain, sub_category)
        sub_desc = sub_info.get('description', sub_category)
        examples = sub_info.get('examples', [])

        intent_guide = DOMAIN_INTENT_GUIDE.get(domain, {})
        intent_type = intent_guide.get('intent_type', '')
        intent_desc = intent_guide.get('description', '')
        key_point = intent_guide.get('key_point', '')
        correct_ex = intent_guide.get('correct_examples', [])
        wrong_ex = intent_guide.get('wrong_examples', [])

        examples_text = "\n".join([f"  - {ex}" for ex in examples[:6]]) if examples else ""
        correct_text = "\n".join([f"  ✓ {ex}" for ex in correct_ex[:4]]) if correct_ex else ""
        wrong_text = "\n".join([f"  ✗ {ex}" for ex in wrong_ex[:4]]) if wrong_ex else ""

        is_traditional_domain = self._is_traditional_domain(domain)
        rewrite_type = self._normalize_rewrite_type_for_domain(rewrite_type, domain)

        if is_traditional_domain:
            if isinstance(rewrite_type, TraditionalRewriteType):
                if rewrite_type == TraditionalRewriteType.PRONOUN:
                    rewrite_instructions = """【改写场景1：有代词，替换为上下文正确实体】
            生成包含代词的追问，需要满足：
            1. 使用代词或指示词（"它"、"这个"、"那个"、"那里"、"这样"等）指代前文提到的实体
            2. 追问必须能够被改写为传统垂域的有效执行指令
            3. 追问要覆盖传统垂域的全功能范围
            4. 生成的追问包含代词，后续会被替换为上下文中的正确实体

            示例：
            - 前文："怎么打开音乐"（用车）
              追问："帮我打开它"（传统）
              说明：使用"它"指代"音乐"，后续改写为"播放音乐"

            - 前文："导航到静安寺"（传统）
              追问："那附近有什么"（传统）
              说明：使用"那"指代"静安寺"，后续改写为"搜索静安寺附近的设施"

            - 前文："温度怎么调节"（用车）
              追问："那我调一下"（传统）
              说明：使用"那"指代"温度"，后续改写为"调节温度" """
                elif rewrite_type == TraditionalRewriteType.ELLIPSIS:
                    rewrite_instructions = """【改写场景2：无代词，根据上下文补充实体】
            生成省略了关键信息的追问，需要满足：
            1. 追问中不要使用代词
            2. 省略前文已提到的关键信息（主语、宾语、对象等）
            3. 省略的内容可以从上下文推断
            4. 追问必须能够被改写和补充为传统垂域的有效执行指令

            示例：
            - 前文："怎么打开音乐"（用车）
              追问："开一下"（传统）
              说明：省略了"音乐"，后续补充为"播放音乐"

            - 前文："导航到静安寺"（传统）
              追问："到了搜索一下"（传统）
              说明：省略了"静安寺"，后续补充为"搜索静安寺附近"

            - 前文："播放周杰伦的歌"（传统）
              追问："换一首更有节奏感的"（传统）
              说明：省略了主语"音乐"和对象，后续补充为"播放一首更有节奏感的音乐"

            - 前文："温度调低"（传统）
              追问："再低一点"（传统）
              说明：省略了"温度"，后续补充为"再调低温度" """
                elif rewrite_type == TraditionalRewriteType.CLARIFICATION:
                    rewrite_instructions = """【改写场景3：语义复杂需剔除无效信息，规整为执行指令】
            生成包含复杂语义的追问，需要满足：
            1. 包含多个动作、修饰词、客套语等复杂表达
            2. 需要简化和规整
            3. 追问必须能够被改写为传统垂域的有效执行指令
            4. 有上下文关联的query必须规整为有效执行指令

            示例：
            - 前文："怎么打开音乐"（用车）
              追问："那个，能不能帮我打开一下，我想听歌"（传统）
              说明：包含客套语、修饰词，后续规整为"播放音乐"

            - 前文："温度设置"（用车）
              追问："其实我想说的是，不是这个温度，应该是25度"（传统）
              说明：包含澄清词和复杂语义，后续规整为"温度调到25度"

            - 前文："导航功能"（用车）
              追问："不好意思，帮我导航到天安门，越快越好"（传统）
              说明：包含客套语、修饰词，后续规整为"导航到天安门"

            - 前文："播放音乐"（传统）
              追问："我想听周杰伦的歌，最好是那种比较轻快的"（传统）
              说明：包含复杂描述，后续规整为"播放周杰伦的轻快歌曲" """
                else:
                    rewrite_instructions = ""
            else:
                rewrite_instructions = ""

            traditional_guidance = """
            【核心要求】
            1. 追问必须是传统垂域的有效执行指令（不能是知识询问）
            2. 追问需要能够覆盖传统垂域的全功能范围（导航、车控、播控、通话、车况查询、日程、车家互联、系统设置、兜底操作等）
            3. 有上下文关联的query必须规整为有效执行指令
            4. 追问要简洁、直接，符合指令语气（生成时可以包含指代、省略、复杂语义，但改写后会规整）
            """
        else:
            if isinstance(rewrite_type, NonTraditionalRewriteType):
                if rewrite_type == NonTraditionalRewriteType.PRONOUN:
                    rewrite_instructions = """【场景1：指代】
            用户在当前对话中使用了代词或指示词来代替之前已经提到的实体或信息。

            生成要求：
            1. 追问中必须包含代词或指示词（"它"、"这个"、"那个"、"那里"、"这样"等）
            2. 代词必须能够在前面对话中找到明确的指代对象
            3. 保持自然对话风格

            示例：
            - 前文："导航到静安寺"（传统）
              追问："那附近有什么好吃的"（出行）
              说明：使用"那"指代"静安寺"

            - 前文："车机系统知识"（用车）
              追问："那个怎么用"（用车）
              说明：使用"那个"指代前文提到的功能"""
                elif rewrite_type == NonTraditionalRewriteType.ELLIPSIS:
                    rewrite_instructions = """【场景2：省略】
            用户在后续的语句中省略了部分内容，但结合上下文仍然能理解完整意图。

            生成要求：
            1. 追问中不要使用代词
            2. 但要省略前文已提到的关键信息（主语、宾语、对象等）
            3. 保持简洁，依赖上下文才能理解完整语义

            示例：
            - 前文："导航到静安寺"（传统）
              追问："到了想买点好吃的"（出行）
              说明：省略了"静安寺附近"

            - 前文："怎么打开音乐"（用车）
              追问："打开一下"（传统）
              说明：省略了"音乐" """
                elif rewrite_type == NonTraditionalRewriteType.VAGUE:
                    rewrite_instructions = """【场景4：模糊】
            用户表达含糊或不完整，需要系统结合上下文或进一步询问才能确定意图。

            生成要求：
            1. 使用模糊词（"好像"、"大概"、"可能"、"也许"、"应该"、"差不多"等）
            2. 缺失关键槽位或表达不完整
            3. 依赖上下文才能确定完整意图

            示例：
            - 前文："导航到静安"（传统，不完整）
              追问："静安寺附近好吃的小店"（出行）
              说明：前文模糊，追问补充POI

            - 前文："怎么操作那个"（用车，模糊）
              追问："是调节温度吗"（用车）
              说明：需要进一步确认"""
                elif rewrite_type == NonTraditionalRewriteType.CLARIFICATION:
                    rewrite_instructions = """【场景3：澄清】
            用户对之前系统的回答或行为提出修正、补充或澄清，通常带有纠错或细化意图。

            生成要求：
            1. 可以包含澄清词（"不是"、"其实"、"更正"、"应该是"等）
            2. 表达对前文的修正或细化
            3. 语义要明确，不是模糊表达

            示例：
            - 前文："导航到静安寺"（传统）
              追问："是静安区"（传统）
              说明：澄清目的地

            - 前文："播放周杰伦的歌"（传统）
              追问："不对，应该是张学友的"（传统）
              说明：澄清要播放的歌手"""
                else:
                    rewrite_instructions = ""
            else:
                rewrite_instructions = ""

            traditional_guidance = ""

        context_condition = f"""
【条件1：语境符合历史问答】核心要求
追问必须严格基于前面的对话历史生成，具体要求：
1. 追问要能够从前面的问答中找到明确的语境关联
2. 追问的内容、实体、动作等要与历史问答相关联
3. 追问要能够自然地延续前面的对话主题
4. 不能生成与前面对话完全无关的追问
5. **追问通过语义隐含关联即可，不要显式回顾前面对话内容（避免"刚才一直在..."等过渡语）**

关键检查点：
- 追问中提到的事物是否在前面对话中出现过或可推断？
- 追问的意图是否与前面对话有逻辑关联？
- 追问能否让人理解是在回应或延续前面对话？
- 追问是否简洁直接，没有不必要的回顾性描述？
"""

        domain_sub_condition = f"""
【条件2：符合当前垂域-子类】核心要求
追问必须严格符合映射指定的垂域和子类：
1. 追问必须属于"{domain}"垂域
2. 追问必须属于"{sub_category}"子类
3. 追问的意图类型必须是"{intent_type}"
4. 追问要符合"{sub_desc}"的范畴

关键检查点：
- 追问是否属于"{domain}"垂域的功能范围？
- 追问是否属于"{sub_category}"的具体范畴？
- 追问是否符合"{intent_type}"的意图类型？
- 追问是否违背了边界规则（如果子类有notices）？
"""

        mapping_emphasis = ""
        if mapping_info and mapping_info.get("is_last_round"):
            scenario_desc = mapping_info.get("scenario_description", "")
            source_domain_name = source_domain or "前一个域"

            mapping_emphasis = f"""
【映射强化要求】
这是跨域映射的最后一轮，从{source_domain_name}转换到{domain}垂域。
场景描述：{scenario_desc}

追问必须同时满足：
1. 语境符合：追问要基于"{source_domain_name}"垂域的前面对话，自然过渡
2. 符合映射：追问必须转换到"{domain}"垂域的"{sub_category}"子类
3. 场景贴合：追问要体现"{scenario_desc}"的场景逻辑
4. 改写方式：必须使用"{rewrite_type.value}"的改写方式

这是一个关键转换点，追问必须既延续前面对话，又切换到目标垂域。
"""
        elif mapping_info and mapping_info.get("is_part_of_mapping"):
            target_sub = mapping_info.get("target_sub_category", "")
            scenario_desc = mapping_info.get("scenario_description", "")
            current_sub = mapping_info.get("current_sub_category", sub_category)

            mapping_emphasis = f"""
【映射背景】（中间轮次）
这是跨域映射的中间轮次，最终会转换到目标子类"{target_sub}"。
场景：{scenario_desc}

当前追问要：
1. 继续深化当前"{current_sub}"的主题
2. 为后续转换到目标子类做铺垫（但不提前涉及目标域内容）
3. 保持与前面对话的强关联性
4. 使用"{rewrite_type.value}"的改写方式
"""

        cross_domain_note = ""
        if is_cross_domain and source_domain:
            cross_domain_note = f"""

            【跨域场景说明】
            这是一个跨域对话场景，用户从{source_domain}垂域转换到{domain}垂域。
            
            重要要求：
            1. 追问要基于前面的对话自然过渡，但不要回顾前面对话的具体内容
            2. 不要使用"刚才一直在..."、"之前我们..."、"刚才说的..."等回顾性过渡语
            3. 追问应该简洁、直接，直接表达当前需求
            4. 追问只需通过语义隐含关联前面对话，不需要显式提及前面对话内容
            5. 如果需要衔接，可以简洁地使用"对了"、"还有"等词，但不要展开回顾
            
            正确示例：
            - 前文："导航到静安寺" 追问："现在感觉有点闷，帮我打开空调吧" ✓（简洁，直接）
            - 前文："导航到静安寺" 追问："打开空调" ✓（简洁，直接）
            
            错误示例：
            - 前文："导航到静安寺" 追问："刚才一直在调导航，现在感觉有点闷，帮我打开空调吧" ✗（包含回顾性过渡语）
            - 前文："导航到静安寺" 追问："之前我们导航的时候，现在想想还是开空调比较好" ✗（过度回顾）
            
            追问仍需保持"{intent_type}"的意图类型，但表达要简洁直接。
            """

        context_rounds = len([line for line in context.split('\n') if '第' in line and '轮' in line])
        if context_rounds == 0:
            context_rounds = len(context.split('\n')) if context else 0

        prompt = f"""你是一个专业的语料生成专家。请生成{domain}垂域中关于"{sub_category}"的多轮对话追问。

            【对话历史】（这是最重要的输入）
            {context}

            {context_condition}

            {domain_sub_condition}

            【垂域说明】
            {domain}：{domain_desc}

            【子类说明】
            {sub_category}：{sub_desc}

            【意图类型】核心要求
            本垂域的意图类型是"{intent_type}"：{intent_desc}
            关键点：{key_point}

            本垂域正确的问题示例：
            {correct_text if correct_text else "  （参考典型示例）"}
            {f'''
            应该避免的问题示例（属于其他垂域）：
            {wrong_text}''' if wrong_text else ''}

            【典型示例】（参考这些示例的意图类型和风格，但生成的追问需要应用改写规则）
            {examples_text if examples_text else "  （参考子类说明）"}

            【改写要求】核心
            {rewrite_instructions}
            {traditional_guidance}
            {mapping_emphasis}
            {cross_domain_note}

            【生成要求】
            1. 生成1条用户追问
            2. 追问必须同时满足两个条件：
               - 条件1：语境符合前面{context_rounds}轮的历史问答（必须有关联！）
               - 条件2：符合"{domain}"垂域的"{sub_category}"子类（必须严格属于！）
            3. 追问的意图类型必须是"{intent_type}"（这是最重要的！）
            4. 追问要基于对话历史，使用"{rewrite_type.value}"的改写方式
            5. 生成的追问必须能够被改写为完整、独立的执行指令或询问句
            6. 严格参考典型示例的意图类型，但应用改写规则变化表达方式
            7. **追问要简洁、直接，不要包含回顾性过渡语（如"刚才一直在..."、"之前我们..."等）**
            8. **追问通过语义隐含关联前面对话即可，不需要显式提及前面对话内容**
            9. 直接返回追问，不要编号、不要解释、不要前缀

            【双重检查清单】
            生成前请检查：
            □ 追问是否与前面对话有明确的语境关联？
            □ 追问是否严格属于"{domain}"垂域的"{sub_category}"子类？
            □ 追问是否符合"{intent_type}"的意图类型？
            □ 追问是否使用了"{rewrite_type.value}"的改写方式？
            □ 追问是否简洁直接，没有包含"刚才一直在..."、"之前我们..."等回顾性过渡语？

            追问："""

        response = await self.generate_corpus(prompt)
        lines = self._parse_lines(response)
        return lines[0] if lines else ""

